package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Closes a period (a soft-closed one too, fixing its figures afresh), fixing its due-total as it is now: the due, as the screen shows it now, of the claims
 *  whose date falls in it that counted by their status at the end of its last day as their status log
 *  records it (n/a ones skipped, and those the live rules leave out: deferred, or OPEN ones dated within
 *  a hold of their person, unless bound).
 *  Each person's due-total for it is fixed too, for everyone on the sheet. Refused when it is already closed, and for a role
 *  the permission matrix does not let close. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            ClaimRepository claims, ClaimLogRepository log, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, RoleRepository roles,
            Out<Period> period) throws InvalidPeriodException, PeriodClosedException, PeriodPermissionException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (!Permissions.allows(id, by, Permissions.CLOSE, roles, settings)) {
            throw new PeriodPermissionException("Your role may not close a period");
        }
        if (found.closed()) {
            throw new PeriodClosedException("The period is already closed");
        }
        period.set(PeriodClosing.closeNow(found, by == null ? "" : by, periods, claims, log, people, rates, settings, sheets));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Soft-closes a period: its due-total and each person's due-total for it are fixed now, as a close
 *  fixes them, but claims due by a day in it can still be added, edited, opened, settled and voided (a claim
 *  added then is a late entry). Refused when it is already closed or soft-closed, and for a role the
 *  permission matrix does not let close. */
public class SoftClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            ClaimRepository claims, ClaimLogRepository log, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, RoleRepository roles,
            Out<Period> period) throws InvalidPeriodException, PeriodClosedException, PeriodPermissionException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (!Permissions.allows(id, by, Permissions.CLOSE, roles, settings)) {
            throw new PeriodPermissionException("Your role may not close a period");
        }
        if (found.fixed()) {
            throw new PeriodClosedException("The period is already closed or soft-closed");
        }
        period.set(PeriodClosing.fixNow(found, by == null ? "" : by, true, periods, claims, log, people, rates, settings, sheets));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Reopens a closed or soft-closed period: its due-total is live again. Refused for a role the permission matrix does not let reopen (by default
 *  anyone but a steward), and when
 *  the period is not closed or is locked. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            RoleRepository roles, SettingRepository settings, Out<Period> period) throws InvalidPeriodException, PeriodReopenException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (!Permissions.allows(id, by, Permissions.REOPEN, roles, settings)) {
            throw new PeriodReopenException("Your role may not reopen a period");
        }
        if (found.locked()) {
            throw new PeriodReopenException("The period is locked");
        }
        if (!found.fixed()) {
            throw new PeriodReopenException("The period is not closed");
        }
        period.set(periods.reopen(found));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSetting;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** How a period is closed: shared by a close by hand ({@link ClosePeriod}) and the auto close of a
 *  today change ({@link AutoClosePeriods}). */
public final class PeriodClosing {
    private PeriodClosing() {
    }

    /** Close the open period now, as a close by hand does (no permission check): used by the
     *  sheet's today change to close the periods past their grace days. */
    public static Period closeNow(Period found, String user, PeriodRepository periods, ClaimRepository claims,
            ClaimLogRepository log, PersonRepository people, RateRepository rates, SettingRepository settings,
            SheetRepository sheets) {
        return fixNow(found, user, false, periods, claims, log, people, rates, settings, sheets);
    }

    /** Close or (soft) soft-close the period now, fixing its figures (and everyone's carried figure) as they are now (no permission check). */
    public static Period fixNow(Period found, String user, boolean soft, PeriodRepository periods, ClaimRepository claims,
            ClaimLogRepository log, PersonRepository people, RateRepository rates, SettingRepository settings,
            SheetRepository sheets) {
        String id = found.sheetId();
        DatedSetting floor = settings.floor(id);
        Dues.Late late = settings.late(id, sheets.today(id));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>();
        for (Person p : people.list(id)) {
            personTotals.put(p.getId(), BigDecimal.ZERO.setScale(2));
            personCarried.put(p.getId(), BigDecimal.ZERO.setScale(2));
        }
        List<Period> earlier = periods.list(id).stream().filter((e) -> e.to().compareTo(found.from()) < 0).toList();
        Map<Long, String> atEnd = log.statusesOn(id, LocalDate.parse(found.to()));
        for (Claim c : claims.list(id)) {
            boolean in = found.contains(c.getDueBy());
            // Carried: due by a day in an earlier period, still OPEN or PENDING at the end of this one.
            boolean carried = !in && earlier.stream().anyMatch((e) -> e.contains(c.getDueBy()));
            if (!in && !carried) continue;
            String status = atEnd.containsKey(c.getId()) ? atEnd.get(c.getId()) : c.getStatus();
            if (status == null || !(ClaimStatus.isOpen(status) || (in && ClaimStatus.SETTLED.name().equals(status)))) continue;
            Person person = people.find(id, c.getPersonId());
            if (person != null && person.leftOutLive(c)) continue;
            Rate rate = person == null ? null
                    : rates.find(id, person.gradeOn(c.getDate()), LocalDate.parse(c.getDate()), c.getId());
            String due = Dues.shown(c, rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
            if (due == null) continue;
            if (carried) {
                if (person != null) personCarried.merge(person.getId(), new BigDecimal(due), BigDecimal::add);
                continue;
            }
            total = total.add(new BigDecimal(due));
            if (person != null) personTotals.merge(person.getId(), new BigDecimal(due), BigDecimal::add);
        }
        // An opening balance is part of the carried figure fixed now.
        found.personOpenings().forEach((pid, amount) -> {
            if (personCarried.containsKey(pid)) personCarried.merge(pid, new BigDecimal(amount), BigDecimal::add);
        });
        return periods.close(found, total, personTotals, personCarried, user, soft);
    }
}
